<?php if (($snapshot['pricing_mode'] ?? null)==='occupancy'): ?><section><h2>Foglalói létszám és occupancy árképzés</h2><dl class="facts"><div><dt>Árazási létszám</dt><dd><?= $e($snapshot['chargeable_guests'] ?? '') ?></dd></div><div><dt>Tényleges vendégek</dt><dd><?= $e($snapshot['physical_guests'] ?? '') ?></dd></div><div><dt>Ingyenes gyermekek (0–3)</dt><dd><?= $e(implode(', ', $snapshot['free_children'] ?? [])) ?: 'nincs' ?></dd></div><div><dt>Egyéjszakás felár</dt><dd><?= $e(\App\Presentation\HufFormatter::format($snapshot['one_night_surcharge'] ?? '0.00')) ?></dd></div><div><dt>Időszakos árak</dt><dd><?= $e(implode(', ', $snapshot['applied_date_override_ids'] ?? [])) ?: 'nincs' ?></dd></div></dl></section><?php endif; ?>
