<?php require __DIR__ . '/_nightly-pricing.php'; ?><section><h2>Lemondási feltételek</h2><?php if (isset($cancellationPreview) && $cancellationPreview !== null): ?><dl class="facts"><div><dt>Díjmentes lemondás határideje</dt><dd><?= $e($cancellationPreview->snapshot['free_cancellation_deadline']) ?></dd></div><div><dt>Mai kötbér-előnézet</dt><dd><?= $e(\App\Presentation\HufFormatter::format($cancellationPreview->penaltyAmount)) ?></dd></div><div><dt>Ár-pillanatkép szállásdíja</dt><dd><?= $e(\App\Presentation\HufFormatter::format($cancellationPreview->snapshot['accommodation_fee'])) ?></dd></div><div><dt>Kötbér mértéke</dt><dd><?= $e(\App\Presentation\PercentFormatter::fromDecimalRate($cancellationPreview->penaltyRate)) ?></dd></div></dl><?php else: ?><p>Az előnézethez nem áll rendelkezésre megfelelő ár-pillanatkép.</p><?php endif ?><?php if (!empty($booking['cancelled_at'])): ?><p>A rögzített lemondás: <?= $e($booking['cancelled_at']) ?>; kötbér: <?= $e(\App\Presentation\HufFormatter::format($booking['cancellation_penalty_amount'])) ?>.</p><?php endif ?></section>
<?php if ($booking['status'] === 'pending'): ?>
